<script setup lang="ts">definePageMeta({layout:'admin'});const q=ref(''),category=ref(''),status=ref(''),page=ref(1);watch([q,category,status],()=>page.value=1);const {data,refresh}=await useFetch('/api/admin/products',{query:{q,category,status,page},transform:(r:any)=>r});const {data:cats}=await useFetch('/api/admin/categories',{transform:(r:any)=>r.data});const {formatIDR}=useCurrency();const date=(v:string)=>v?new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date(v)):'—';async function remove(id:string){if(!confirm('Arsipkan produk ini? Riwayat stok tetap disimpan.'))return;await $fetch(`/api/admin/products/${id}`,{method:'DELETE'});refresh()}</script><template><div class="admin-page"><AdminPageHeader title="Produk" description="Kelola katalog, harga, status, dan stok."><NuxtLink class="btn btn-primary" to="/admin/produk/tambah">Tambah Produk</NuxtLink></AdminPageHeader><div class="filters"><input v-model="q" class="field" placeholder="Cari nama atau SKU"><select v-model="category" class="field"><option value="">Semua kategori</option><option v-for="c in cats" :key="c.id" :value="c.slug">{{c.name}}</option></select><select v-model="status" class="field"><option value="">Semua status</option><option value="active">Aktif</option><option value="inactive">Nonaktif</option><option value="low">Stok menipis</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Foto</th><th>SKU</th><th>Nama</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th>Updated</th><th>Aksi</th></tr></thead><tbody><tr v-for="p in data?.data" :key="p.id"><td><NuxtImg :src="p.coverImage.url" :alt="p.coverImage.alt" width="48" height="40"/></td><td>{{p.sku}}</td><td><b>{{p.name}}</b></td><td>{{p.category.name}}</td><td>{{formatIDR(p.price)}}</td><td>{{p.stock}}</td><td>{{p.isActive?'Aktif':'Nonaktif'}}</td><td>{{date(p.updatedAt)}}</td><td><NuxtLink :to="`/admin/produk/${p.id}/edit`">Edit</NuxtLink> · <button @click="remove(p.id)">Arsip</button></td></tr></tbody></table></div><div class="pages"><button :disabled="page<=1" @click="page--">Sebelumnya</button><span>Halaman {{page}} / {{data?.meta.totalPages}}</span><button :disabled="page>=data?.meta.totalPages" @click="page++">Berikutnya</button></div></div></template><style scoped>.filters{display:grid;grid-template-columns:1fr 220px 180px;gap:.7rem}.data-table img{width:48px;height:40px;object-fit:cover;border-radius:6px}.data-table button,.data-table a{border:0;background:none;color:var(--gold-dark)}.pages{display:flex;justify-content:center;gap:1rem}.pages button{border:1px solid var(--border);background:white;padding:.5rem;border-radius:8px}@media(max-width:700px){.filters{grid-template-columns:1fr}}</style>
